preConditionHook:
// Level forward drift (Brian's notes P1b, triage row P1). The P1 visit scan: a
// VISIT is a bar kk bars ago, minGap <= kk <= lookback, whose low..high range
// contains the current close (inclusive, el_le/el_ge). Only visits with a
// complete, strictly past forward window count (kk > horizon). Forward move =
// close[kk - horizon] - close[kk], from the visit bar's close. LONG when at
// least minVisits such visits exist and their mean move is at least driftAtr x
// the CURRENT ATR; SHORT when at most -driftAtr x it. Mean guarded on a zero
// count, as the EL twin must be (EL raises on a zero denominator).
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, SwingLowRejection's
// block verbatim -- seeded with a full N-term sum on the first calculated bar or
// when the length changes, and after that TWO statements (S += in; S -= out;) --
// EL evaluates S[1] + in - out left to right. It stays in the hook, which the
// generator emits unconditionally.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLookback; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLookback;
} else {
    outIdx = (int)atrLookback;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLookback;
hh = (int)horizon;
forwardCount = 0;
forwardSum = 0.0;
for (kk = (int)minGap; kk <= (int)lookback; ++kk) {
    if (el_le(low[kk], close[0]) && el_ge(high[kk], close[0])) {
        if (kk > hh) {
            forwardCount = forwardCount + 1;
            forwardSum = forwardSum + (close[kk - hh] - close[kk]);
        }
    }
}
meanMove = 0.0;
if (forwardCount > 0) meanMove = forwardSum / forwardCount;
enoughVisits = el_ge(forwardCount, minVisits) && el_gt(forwardCount, 0);
